// LexicalAnalysis.cpp : 此文件包含 "main" 函数。程序执行将在此处开始并结束。
//
#include <iostream>
#include <cstring>
#include <fstream>
#include <sstream>
#include <vector>
#include <ctype.h>
#include <set>
#include <iomanip>
#include <map>
using namespace std;


//美化输出
void printTask(const string tip,const string placeholder) {
	int len = 80 - tip.length();
	int left = len / 2;
	int right = len - left;
	cout << "|";
	for (int i = 0; i < left; i++) {
		cout << placeholder;
	}
	cout << tip;
	for (int i = 0; i < right; i++) {
		cout << placeholder;
	}
	cout << "|" << endl;
}
void printTips(const string tip) {
	cout << "|********************************************************************************|" << endl;
	printTask(tip,"*");
	cout << "|********************************************************************************|" << endl;
	cout << endl;
}

//单词类别信息
struct wtPair{
	int idx;
	int type;
	string value;
	wtPair(int a, int b, string c) :idx(a), type(b), value(c) {}
};

//非法单词的类别码
const int WT_ILLEGAL = 0;
//原始源程序文件，不合规单词的行列定位以它为基准
const string rawFileName = "./testCpp.txt";

//预处理程序
bool preProcess(const string fileName, const string newFileName) {
	printTips("开始预处理");
	//打开待分析的源程序文件
	ifstream in(fileName.c_str());
	if (!in) {
		cout << "源程序文件" << fileName << "打开失败！" << endl;
		return false;
	}
	//将源程序整体读入字符串缓冲区，注释、空白的清理留给后续阶段
	stringstream buffer;
	buffer << in.rdbuf();
	string code = buffer.str();
	in.close();

	//去除注释：既支持"//"行注释，也支持可以跨行的"/* */"块注释
	string noComment = "";
	for (size_t i = 0; i < code.length(); i++) {
		if (code[i] == '/' && i + 1 < code.length() && code[i + 1] == '/') {
			//行注释：丢弃"//"之后的全部字符，行末的换行符留给空白处理阶段
			while (i < code.length() && code[i] != '\n') {
				i++;
			}
			if (i < code.length()) {
				noComment += code[i];
			}
		}
		else if (code[i] == '/' && i + 1 < code.length() && code[i + 1] == '*') {
			//块注释：丢弃"/*"之后的全部字符，直至配对的"*/"
			i += 2;
			while (i + 1 < code.length() && !(code[i] == '*' && code[i + 1] == '/')) {
				i++;
			}
			i++;
		}
		else {
			noComment += code[i];
		}
	}
	code = noComment;

	//清理空白：删除回车换行与制表符，并把连续的多个空格压缩成一个空格
	string clean = "";
	for (size_t i = 0; i < code.length(); i++) {
		if (code[i] == '\n' || code[i] == '\r' || code[i] == '\t') {
			continue;
		}
		if (code[i] == ' ' && !clean.empty() && clean[clean.length() - 1] == ' ') {
			continue;
		}
		clean += code[i];
	}
	code = clean;

	//以字符流的形式显示预处理后的源程序
	printTask("预处理后的源程序字符流", "-");
	cout << code << endl << endl;

	//将预处理结果写入与源程序同目录的新文件
	ofstream out(newFileName.c_str());
	if (!out) {
		cout << "预处理结果文件" << newFileName << "创建失败！" << endl;
		return false;
	}
	out << code;
	out.close();
	cout << "预处理结果已保存至" << newFileName << endl << endl;
	printTips("预处理已完成");
	return true;
}

//判断单词是否是变量名
bool IsIdentifier(const string word) {
	if (word.empty()) {
		return false;
	}
	//首字符只能是字母或下划线
	if (!isalpha((unsigned char)word[0]) && word[0] != '_') {
		return false;
	}
	//其余字符只能是字母、数字或下划线
	for (size_t i = 1; i < word.length(); i++) {
		if (!isalnum((unsigned char)word[i]) && word[i] != '_') {
			return false;
		}
	}
	return true;
}
//判断单词是否是数字
bool IsNum(const string word) {
	//十进制整数：首位之后的每一个字符都必须是数字
	for (size_t i = 1; i < word.length(); i++) {
		if (!isdigit((unsigned char)word[i])) {
			return false;
		}
	}
	return true;
}
//判断单词类型
int wtMatch(const string word) {
	//关键字与运算符、界符的单词-类型关系表
	static map<string, int> wtTable;
	if (wtTable.empty()) {
		wtTable["void"] = 1;
		wtTable["main"] = 2;
		wtTable["int"] = 3;
		wtTable["cout"] = 4;
		wtTable["return"] = 5;
		wtTable["("] = 6;
		wtTable[")"] = 7;
		wtTable["{"] = 8;
		wtTable["}"] = 9;
		wtTable["<<"] = 10;
		wtTable[";"] = 11;
		wtTable[","] = 12;
		wtTable["="] = 13;
		wtTable["*"] = 14;
		wtTable["/"] = 15;
	}
	map<string, int>::const_iterator it = wtTable.find(word);
	if (it != wtTable.end()) {
		return it->second;
	}
	//表中查不到的单词，再依次判断是否为标识符、十进制整数
	if (IsIdentifier(word)) {
		return 16;
	}
	if (IsNum(word)) {
		return 17;
	}
	//既不是标识符也不是十进制整数，属于非法单词
	return WT_ILLEGAL;
}
//在原始源程序中定位某个不合规单词，返回其所有出现位置
string findError(const string fileName, const string value) {
	ifstream in(fileName.c_str());
	if (!in) {
		cout << "源程序文件" << fileName << "打开失败！" << endl;
		return "";
	}
	string position = "";
	string line = "";
	int row = 0;
	//逐行读入原始源程序，在行内反复查找该单词，记录其行号与列号
	while (getline(in, line)) {
		row++;
		size_t col = line.find(value);
		while (col != string::npos) {
			ostringstream oss;
			oss << "第" << row << "行第" << col << "列";
			position += oss.str();
			col = line.find(value, col + 1);
		}
	}
	in.close();
	return position;
}
bool mainProcess(const string fileName, const string fileNameProcessed) {
	printTips("开始单词扫描");
	//读入预处理后的源程序字符流
	ifstream in(fileName.c_str());
	if (!in) {
		cout << "预处理结果文件" << fileName << "打开失败！" << endl;
		return false;
	}
	stringstream buffer;
	buffer << in.rdbuf();
	string code = buffer.str();
	in.close();

	//扫描字符流：以空格和界符为分隔，切分出一个个单词并顺次匹配其类别
	const string delimiter = "(){}[];,=*/<>+-!%&|";
	vector<wtPair> words;
	string word = "";
	int idx = 0;
	for (size_t i = 0; i < code.length(); i++) {
		char c = code[i];
		bool isDelimiter = (delimiter.find(c) != string::npos);
		if (c != ' ' && !isDelimiter) {
			//字母、数字、下划线等构成单词主体，先累积起来
			word += c;
			continue;
		}
		//空格与界符都意味着上一个单词的结束
		if (!word.empty()) {
			words.push_back(wtPair(++idx, wtMatch(word), word));
			word = "";
		}
		if (!isDelimiter) {
			continue;
		}
		//界符自身也是单词，"<<"这类双字符运算符需要向前多看一个字符
		string op(1, c);
		if (i + 1 < code.length() && delimiter.find(code[i + 1]) != string::npos) {
			string two = op + code[i + 1];
			if (wtMatch(two) != WT_ILLEGAL) {
				op = two;
				i++;
			}
		}
		words.push_back(wtPair(++idx, wtMatch(op), op));
	}
	//字符流末尾可能还留有一个未收尾的单词
	if (!word.empty()) {
		words.push_back(wtPair(++idx, wtMatch(word), word));
	}
	cout << "共扫描出" << words.size() << "个单词" << endl << endl;

	//输出单词-类型表：合规单词以<序号，类别码，值>的形式显示，非法单词只登记不显示
	ostringstream report;
	vector<wtPair> errorSeq;
	report << setw(8) << "单词序号" << setw(12) << "单词类别" << setw(12) << "单词" << endl;
	for (size_t i = 0; i < words.size(); i++) {
		if (words[i].type == WT_ILLEGAL) {
			errorSeq.push_back(words[i]);
			continue;
		}
		report << setw(8) << words[i].idx << setw(12) << words[i].type
			<< setw(12) << words[i].value << endl;
	}

	//不合规单词的出错信息：按单词的值去重，给出其序号并在原程序中定位
	if (!errorSeq.empty()) {
		report << "不合规单词：" << endl;
		set<string> printed;
		for (size_t i = 0; i < errorSeq.size(); i++) {
			if (!printed.insert(errorSeq[i].value).second) {
				continue;
			}
			report << "  " << errorSeq[i].value << ": " << endl;
			report << "    ";
			for (size_t j = i; j < errorSeq.size(); j++) {
				if (errorSeq[j].value == errorSeq[i].value) {
					report << "第" << errorSeq[j].idx << "个单词;";
				}
			}
			report << endl;
			report << "    位于" << findError(rawFileName, errorSeq[i].value) << endl;
		}
	}
	cout << report.str();
	return true;
}


int main()
{
	string fileName = "./testCpp.txt";
	string afterPreProcess = "./afterPreProcess.txt";
	string processed = "./processed.txt";
	printTips("开始词法分析");
	if (preProcess(fileName, afterPreProcess)) {
		if (mainProcess(afterPreProcess, processed)) {
			printTips("词法分析已完成");
		}
	}
}

