/**
 * Description: 函数实现以及各类操作符重载
 * Author: 杜登宇
 **/

string load_file(string file_name) {
	cout << "正在读取文法文件：" << file_name << endl;
	ifstream in(file_name.c_str());
	if (!in) {
		cout << "文法文件" << file_name << "打开失败！" << endl;
		return "";
	}
	//将文件内容整体流入字符串
	stringstream buffer;
	buffer << in.rdbuf();
	string text = buffer.str();
	in.close();
	cout << "读取成功，该文法为：" << endl << text << endl << endl;
	return text;
}
ostream& operator << (ostream& out, rule rule) {
	//规则形如 left::=right1|right2|...
	out << rule.left << "::=";
	for (size_t i = 0; i < rule.right.size(); i++) {
		if (i != 0) {
			out << "|";
		}
		out << rule.right[i];
	}
	return out;
}
void split_into_rules(const string text, vector<rule> &rules, set<char> &non_terminal, set<char> &terminal, set<string> &right_parts) {
	//去掉文法中的全部空白字符，便于按"::="切分规则
	string compact = "";
	for (size_t i = 0; i < text.length(); i++) {
		if (!isspace((unsigned char)text[i])) {
			compact += text[i];
		}
	}
	//定位每一个"::="，紧邻其前的字符即为该规则的左部
	vector<size_t> marks;
	for (size_t i = compact.find("::="); i != string::npos; i = compact.find("::=", i + 3)) {
		marks.push_back(i);
	}
	for (size_t k = 0; k < marks.size(); k++) {
		if (marks[k] == 0) {
			continue;
		}
		char left = compact[marks[k] - 1];
		non_terminal.insert(left);
		//右部一直延伸到下一条规则的左部之前
		size_t from = marks[k] + 3;
		size_t to = (k + 1 < marks.size()) ? marks[k + 1] - 1 : compact.length();
		string right = (from < to) ? compact.substr(from, to - from) : "";
		//同一非终结符的多条产生式合并进同一条规则
		size_t at = rules.size();
		for (size_t i = 0; i < rules.size(); i++) {
			if (rules[i].left == left) {
				at = i;
				break;
			}
		}
		if (at == rules.size()) {
			rule new_rule;
			new_rule.left = left;
			rules.push_back(new_rule);
		}
		//右部以"|"分隔成一个个候选符号串
		string part = "";
		for (size_t i = 0; i <= right.length(); i++) {
			if (i == right.length() || right[i] == '|') {
				if (!part.empty()) {
					rules[at].right.push_back(part);
					right_parts.insert(part);
				}
				part = "";
			}
			else {
				part += right[i];
			}
		}
	}
	//右部中既不是非终结符、也不是ε（@）的符号就是终结符
	for (set<string>::const_iterator it = right_parts.begin(); it != right_parts.end(); ++it) {
		for (size_t i = 0; i < it->length(); i++) {
			char c = (*it)[i];
			if (c != '@' && non_terminal.find(c) == non_terminal.end()) {
				terminal.insert(c);
			}
		}
	}
}
void check_rules(const vector<rule> rules) {
	cout << "提取文法规则：" << endl;
	for (size_t i = 0; i < rules.size(); i++) {
		cout << "    " << rules[i] << endl;
	}
	cout << endl;
}
template <class T>
void check_set(set<T> set_, string tip) {
	cout << tip << "：";
	for (typename set<T>::const_iterator it = set_.begin(); it != set_.end(); ++it) {
		if (it != set_.begin()) {
			cout << "  ";
		}
		cout << *it;
	}
	cout << endl << endl;
}
ostream& operator << (ostream& out, F_set f_set) {
	//First集与Follow集共用该结构，靠is_first区分提示信息
	out << (f_set.is_first ? "First(" : "Follow(") << f_set.left << ")={";
	for (set<char>::const_iterator it = f_set.right.begin(); it != f_set.right.end(); ++it) {
		if (it != f_set.right.begin()) {
			out << ",";
		}
		out << *it;
	}
	out << "}";
	return out;
}
F_set findFirst(const string ss, vector<rule> rules) {
	F_set f_set;
	f_set.is_first = true;
	f_set.left = ss;
	//记录正在求解的符号串，避免文法带有递归时无穷递归
	static set<string> visiting;
	if (!visiting.insert(ss).second) {
		return f_set;
	}
	//符号串中的符号逐个考察，只要前一个符号能推出ε就继续看下一个
	bool all_empty = true;
	for (size_t i = 0; i < ss.length(); i++) {
		char c = ss[i];
		size_t at = rules.size();
		for (size_t j = 0; j < rules.size(); j++) {
			if (rules[j].left == c) {
				at = j;
				break;
			}
		}
		if (at == rules.size()) {
			//终结符（含ε）本身就是First集元素，且不再向后传递
			f_set.right.insert(c);
			all_empty = false;
			break;
		}
		//非终结符：把它每一条产生式右部的First集并进来
		bool has_empty = false;
		for (size_t j = 0; j < rules[at].right.size(); j++) {
			string alt = rules[at].right[j];
			if (alt == "@") {
				has_empty = true;
				continue;
			}
			F_set sub = findFirst(alt, rules);
			for (set<char>::const_iterator it = sub.right.begin(); it != sub.right.end(); ++it) {
				if (*it == '@') {
					has_empty = true;
				}
				else {
					f_set.right.insert(*it);
				}
			}
		}
		//该非终结符推不出ε时，后面的符号不再影响First集
		if (!has_empty) {
			all_empty = false;
			break;
		}
	}
	//整个符号串都能推出ε（空串也是如此），则ε属于其First集
	if (all_empty) {
		f_set.right.insert('@');
	}
	visiting.erase(ss);
	return f_set;
}
vector<F_set> checkFirst(set<string> right_parts, vector<rule> rules) {
	vector<F_set> f_sets;
	cout << "各规则右部符号串的First集：" << endl;
	for (set<string>::const_iterator it = right_parts.begin(); it != right_parts.end(); ++it) {
		F_set f_set = findFirst(*it, rules);
		cout << "    " << f_set << endl;
		f_sets.push_back(f_set);
	}
	cout << endl;
	return f_sets;
}
F_set findFollow(const char non_terminal, vector<rule> rules) {
	F_set f_set;
	f_set.is_first = false;
	f_set.left = non_terminal;
	//输入串结束符恒属于Follow集
	f_set.right.insert('#');
	//记录正在求解的非终结符，避免文法互相引用时无穷递归
	static set<char> visiting;
	if (!visiting.insert(non_terminal).second) {
		return f_set;
	}
	//在所有产生式右部中寻找该非终结符
	for (size_t i = 0; i < rules.size(); i++) {
		for (size_t j = 0; j < rules[i].right.size(); j++) {
			string alt = rules[i].right[j];
			for (size_t k = 0; k < alt.length(); k++) {
				if (alt[k] != non_terminal) {
					continue;
				}
				string suffix = alt.substr(k + 1);
				bool to_parent = false;
				if (suffix.empty()) {
					//该非终结符位于右部末尾，其Follow集包含左部的Follow集
					to_parent = true;
				}
				else {
					//否则由后继符号串的First集决定，ε则继续追加左部的Follow集
					F_set first = findFirst(suffix, rules);
					for (set<char>::const_iterator it = first.right.begin(); it != first.right.end(); ++it) {
						if (*it == '@') {
							to_parent = true;
						}
						else {
							f_set.right.insert(*it);
						}
					}
				}
				if (to_parent && rules[i].left != non_terminal) {
					F_set parent = findFollow(rules[i].left, rules);
					f_set.right.insert(parent.right.begin(), parent.right.end());
				}
			}
		}
	}
	visiting.erase(non_terminal);
	return f_set;
}
vector<F_set> checkFollow(set<char> non_terminal, vector<rule> rules) {
	vector<F_set> f_sets;
	cout << "各非终结符的Follow集：" << endl;
	for (set<char>::const_iterator it = non_terminal.begin(); it != non_terminal.end(); ++it) {
		F_set f_set = findFollow(*it, rules);
		cout << "    " << f_set << endl;
		f_sets.push_back(f_set);
	}
	cout << endl;
	return f_sets;
}
