		is_sentence = false;
		break;
	}
	rule cell = table.rules[i * table.col.size() + j];
	if (cell.right.empty()) {
		//查到的是出错项，分析失败
		is_sentence = false;
		break;
	}
	//用产生式右部替换栈顶的非终结符，右部为ε时只弹出
	analysis_s.pop();
	string right = cell.right[0];
	if (right != "@") {
		for (size_t k = right.length(); k > 0; k--) {
			analysis_s.push(right[k - 1]);
		}
	}
	rule_temp = cell;
	print_state(analysis_s, input_s, rule_temp);
