void syntacticAnalysis(LL_1_table table) {
	cout << endl << "接下来进行语法分析" << endl << "请输入字符串：" << endl;
	string input;
	cin >> input;

	//输入栈：'#'在栈底，待分析的字符串自右向左压入
	stack<char> input_s;
	input_s.push('#');
	for (size_t i = input.length(); i > 0; i--) {
		input_s.push(input[i - 1]);
	}
	//分析栈：'#'在栈底，其上是文法开始符号（行表头中的第一个非终结符）
	stack<char> analysis_s;
	analysis_s.push('#');
	if (!table.row.empty()) {
		analysis_s.push(table.row[0]);
	}
	//分析结论标志，一旦出现无法匹配的情况即置为false
	bool is_sentence = true;

	cout << endl << "分析过程如下：" << endl;
	cout << setw(20) << "分析栈" << setw(20) << "剩余输入串" << setw(20) << "所用产生式" << endl;
	rule rule_temp;
	rule_temp.left = ' ';
	print_state(analysis_s, input_s, rule_temp);

	//自顶向下的表驱动分析：栈顶为非终结符时查表展开，为终结符时与输入串匹配
	while (is_sentence && !analysis_s.empty() && !input_s.empty()) {
		char top = analysis_s.top();
		char cur = input_s.top();
		if (top == '#') {
			//分析栈只剩'#'，输入串也恰好读完则分析成功
			is_sentence = (cur == '#');
			break;
		}
		size_t i = find(table.row.begin(), table.row.end(), top) - table.row.begin();
		if (i == table.row.size()) {
			//终结符：与当前输入字符匹配则同时弹出，否则分析失败
			if (top != cur) {
				is_sentence = false;
				break;
			}
			analysis_s.pop();
			input_s.pop();
			rule_temp.right.clear();
			print_state(analysis_s, input_s, rule_temp);
			continue;
		}
		size_t j = find(table.col.begin(), table.col.end(), cur) - table.col.begin();
		if (j == table.col.size()) {
			//当前输入字符不是该文法的终结符，分析失败
			is_sentence = false;
			break;
		}
		rule cell = table.rules[i * table.col.size() + j];
		if (cell.right.empty()) {
			//查到的是出错项，分析失败
			is_sentence = false;
			break;
		}
		//用产生式右部替换栈顶的非终结符，右部为ε时只弹出
		analysis_s.pop();
		string right = cell.right[0];
		if (right != "@") {
			for (size_t k = right.length(); k > 0; k--) {
				analysis_s.push(right[k - 1]);
			}
		}
		rule_temp = cell;
		print_state(analysis_s, input_s, rule_temp);
	}

	cout << endl << "字符串" << input;
	if (!is_sentence) {
		cout << "不";
	}
	cout << "是该文法的句子";
}

